import { useFocusEffect } from '@react-navigation/native';
import { useCallback, useEffect, useRef, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';
import { Button } from '../components/Button';
import ExpoTranscribe from '../modules/expo-transcribe';

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export function TranscribeScreen() {
  const [statusLine, setStatusLine] = useState('Speech access: not requested');
  const [authorized, setAuthorized] = useState(false);
  const [isTranscribing, setIsTranscribing] = useState(false);
  const [transcript, setTranscript] = useState<string | null>(null);
  const [elapsedSeconds, setElapsedSeconds] = useState<number | null>(null);
  const startedAtRef = useRef<number>(0);

  useEffect(() => {
    const subscription = ExpoTranscribe.addListener('onPartialResult', ({ text }) => {
      setTranscript(text);
    });
    return () => subscription.remove();
  }, []);

  const refreshStatus = useCallback(() => {
    const status = ExpoTranscribe.getAuthorizationStatus();
    setStatusLine(`Speech access: ${status}`);
    setAuthorized(status === 'granted');
  }, []);

  useFocusEffect(
    useCallback(() => {
      refreshStatus();
    }, [refreshStatus])
  );

  const handleRequestAccess = async () => {
    try {
      const status = await ExpoTranscribe.requestAuthorization();
      setStatusLine(`Speech access: ${status}`);
      setAuthorized(status === 'granted');
    } catch (error) {
      setStatusLine(errorMessage(error));
    }
  };

  const handleTranscribe = async () => {
    setIsTranscribing(true);
    setStatusLine('Transcribing…');
    setTranscript(null);
    setElapsedSeconds(null);
    startedAtRef.current = Date.now();
    try {
      const finalTranscript = await ExpoTranscribe.transcribeSample();
      setTranscript(finalTranscript);
      setElapsedSeconds((Date.now() - startedAtRef.current) / 1000);
      setStatusLine('Speech access: granted');
    } catch (error) {
      setStatusLine(errorMessage(error));
    } finally {
      setIsTranscribing(false);
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.status}>{statusLine}</Text>
      <View style={styles.buttons}>
        <Button label="Request Access" onPress={handleRequestAccess} />
        <Button
          label="Transcribe Sample"
          onPress={handleTranscribe}
          disabled={!authorized || isTranscribing}
        />
      </View>
      <View style={styles.transcriptArea}>
        {transcript ? (
          <>
            <Text style={styles.transcript}>{transcript}</Text>
            {elapsedSeconds !== null && (
              <Text style={styles.completed}>Completed in {elapsedSeconds.toFixed(1)} s</Text>
            )}
          </>
        ) : (
          <Text style={styles.emptyState}>No transcript yet</Text>
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 24,
    gap: 16,
  },
  status: {
    fontSize: 15,
    color: '#333',
  },
  buttons: {
    gap: 12,
  },
  transcriptArea: {
    marginTop: 16,
    flex: 1,
  },
  transcript: {
    fontSize: 17,
    color: '#333',
    lineHeight: 24,
  },
  completed: {
    marginTop: 12,
    fontSize: 13,
    color: '#8E8E93',
  },
  emptyState: {
    fontSize: 15,
    color: '#8E8E93',
  },
});

